PKG=ROOT/"qseries_v2/oracle_strategy_intelligence/solana_money"
MOD=PKG/"qsb059_gav_reverse_atomic.py"
MOD.write_text('from __future__ import annotations\nimport base64,json,os,struct\nfrom pathlib import Path\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.native_atomic_money_machine import core as c\n\nCASE_REPORT="runtime_state/qseries/qsb058_gav_profitable_case/report.json"\nMIN_NET_BPS=float(os.getenv("QSB_059_MIN_NET_BPS","20"))\nSLIPPAGE_BPS=int(os.getenv("QSB_059_SLIPPAGE_BPS","20"))\n\ndef load_case(root):\n    p=Path(root)/CASE_REPORT\n    if not p.is_file():\n        raise RuntimeError("QSB058_REPORT_MISSING")\n    r=json.loads(p.read_text(encoding="utf-8"))\n    b=r.get("binding") or {}\n    if not b.get("resolved") or not b.get("current_binding_ok"):\n        raise RuntimeError("QSB058_BINDING_NOT_READY")\n    return r,b\n\ndef dlmm_reverse_ix(user,meta,input_amount,quote_result):\n    pool=meta["address"]\n    tx_prog=c.account(meta["token_x"])[1]\n    ty_prog=c.account(meta["token_y"])[1]\n    ux=c.ata(user,meta["token_x"],tx_prog)\n    uy=c.ata(user,meta["token_y"],ty_prog)\n    rx=c.pda([c.b58d(pool),c.b58d(meta["token_x"])],c.DLMM)\n    ry=c.pda([c.b58d(pool),c.b58d(meta["token_y"])],c.DLMM)\n    oracle=c.pda([b"oracle",c.b58d(pool)],c.DLMM)\n    bitmap=c.pda([b"bitmap",c.b58d(pool)],c.DLMM)\n    try:\n        c.account(bitmap)\n        bitmap_key=bitmap\n    except Exception:\n        bitmap_key=c.DLMM\n    ev=c.pda([b"__event_authority"],c.DLMM)\n\n    # Reverse direction is token -> WSOL.\n    if meta["token_x"]==c.WSOL:\n        source=uy;dest=ux\n        swap_for_y=False\n    elif meta["token_y"]==c.WSOL:\n        source=ux;dest=uy\n        swap_for_y=True\n    else:\n        raise RuntimeError("DLMM_PAIR_NOT_WSOL")\n\n    if bool(quote_result.get("swap_for_y"))!=swap_for_y:\n        raise RuntimeError("DLMM_QUOTE_DIRECTION_MISMATCH")\n\n    ac=[\n      (pool,False,True),(bitmap_key,False,True),(rx,False,True),(ry,False,True),\n      (source,False,True),(dest,False,True),\n      (meta["token_x"],False,False),(meta["token_y"],False,False),(oracle,False,True),\n      (c.DLMM,False,True),(user,True,False),(tx_prog,False,False),(ty_prog,False,False),\n      (ev,False,False),(c.DLMM,False,False)\n    ]\n\n    arr=c.dlmm_arrays(pool)\n    n=min(len(arr),max(3,int(quote_result.get("bins_crossed") or 1)+2))\n    chosen=arr[:n] if swap_for_y else list(reversed(arr))[:n]\n    ac += [(x[1],False,True) for x in chosen]\n\n    min_out=int(quote_result["raw_out"])*(10000-SLIPPAGE_BPS)//10000\n    data=bytes([248,198,158,145,225,117,135,200])+struct.pack("<QQ",int(input_amount),min_out)\n    return {\n        "programId":c.DLMM,\n        "accounts":[{"pubkey":p,"isSigner":s,"isWritable":w} for p,s,w in ac],\n        "data":base64.b64encode(data).decode(),\n    }\n\ndef compose_reverse_atomic(user,token,pump_pool,meteora_pool,start_sol):\n    start=int(round(float(start_sol)*1e9))\n\n    meta=c.discover_dlmm(token)\n    if meta["address"]!=meteora_pool:\n        raise RuntimeError("METEORA_BINDING_DRIFT")\n\n    # Leg 1: WSOL -> token on PumpSwap, using Pump\'s own current executable transaction quote.\n    pump64,pump_token_out=c.pump_tx(user,c.WSOL,token,start)\n    if pump_token_out<=0:\n        raise RuntimeError("PUMP_BUY_OUTPUT_ZERO")\n\n    # Leg 2: token -> WSOL on Meteora from current raw pool/bin state.\n    mq=c.dlmm_quote(meta,pump_token_out,token)\n    end=int(mq["raw_out"])\n    local_net=end-start\n    local_bps=local_net/start*10000.0\n\n    p_ixs,alts=c.resolve_pump_instructions(pump64)\n    m_ix=dlmm_reverse_ix(user,meta,pump_token_out,mq)\n\n    # Preserve all Pump setup/ATA/compute instructions, then insert Meteora immediately\n    # after the actual PumpSwap program instruction, keeping both legs in one transaction.\n    ixs=[];inserted=False\n    for ix in p_ixs:\n        ixs.append(ix)\n        if ix["programId"]==c.PUMP and not inserted:\n            ixs.append(m_ix)\n            inserted=True\n    if not inserted:\n        raise RuntimeError("PUMP_PROGRAM_IX_NOT_FOUND")\n\n    return {\n        "start_lamports":start,\n        "pump_token_out_raw":pump_token_out,\n        "meteora_end_lamports":end,\n        "pre_sim_net_lamports":local_net,\n        "pre_sim_bps":local_bps,\n        "instructions":ixs,\n        "alts":alts,\n        "meta":meta,\n    }\n\ndef run(root=None,start_sol=0.05):\n    root=Path(root or Path.cwd())\n    report,binding=load_case(root)\n    token=binding["token"]\n    pump_pool=binding["pump_pool"]\n    meteora_pool=binding["meteora_pool"]\n\n    kp,user=c.sim_identity()\n    print("[QSB-059] GAV PUMP->METEORA NATIVE ATOMIC COMPOSER",flush=True)\n    print("[CASE] token=%s pump=%s meteora=%s"%(token,pump_pool,meteora_pool),flush=True)\n    print("[SIZE] %.6f SOL"%float(start_sol),flush=True)\n    print("[SIGNER] %s"%("LOCAL_PRIVATE_KEY" if kp is not None else "SIM_ONLY_PUBLIC_KEY"),flush=True)\n\n    x=compose_reverse_atomic(user,token,pump_pool,meteora_pool,float(start_sol))\n    print("[PRE_SIM] net=%+.9f SOL bps=%+.2f"%(\n        x["pre_sim_net_lamports"]/1e9,x["pre_sim_bps"]),flush=True)\n\n    bh=c.rpc("getLatestBlockhash",[{"commitment":"processed"}])["value"]["blockhash"]\n    msg,unsigned=c.compile_v0(user,x["instructions"],x["alts"],bh)\n    raw=c.signed_tx(msg,kp) if kp is not None else unsigned\n    sim=c.simulate(raw,user,sigverify=(kp is not None))\n    pnl=sim["pnl"]\n    bps=(pnl/x["start_lamports"]*10000.0 if pnl is not None else None)\n    good=sim["err"] is None and pnl is not None and pnl>0 and bps>=MIN_NET_BPS\n\n    print("[SIM_PNL] net=%s SOL bps=%s units=%s err=%s PROFITABLE=%s"%(\n        ("%+.9f"%(pnl/1e9) if pnl is not None else "NA"),\n        ("%+.2f"%bps if bps is not None else "NA"),\n        sim.get("units"),sim.get("err"),good),flush=True)\n\n    out=root/"runtime_state/qseries/qsb059_gav_reverse_atomic/report.json"\n    out.parent.mkdir(parents=True,exist_ok=True)\n    payload={\n        "revision":"QSB_059_GAV_REVERSE_ATOMIC_COMPOSER_V1",\n        "token":token,"pump_pool":pump_pool,"meteora_pool":meteora_pool,\n        "direction":"PUMP_TO_METEORA","start_sol":float(start_sol),\n        "pre_sim_net_sol":x["pre_sim_net_lamports"]/1e9,\n        "pre_sim_bps":x["pre_sim_bps"],\n        "sim_err":sim.get("err"),"sim_units":sim.get("units"),\n        "sim_pnl_sol":None if pnl is None else pnl/1e9,\n        "sim_bps":bps,"profitable_simulation":good,\n        "execution_authority":False,"real_money_moved":False,\n        "next_required_boundary":"QSB_060_LIVE_PROFIT_GATE_AND_BROADCAST_ARM" if good else "REPAIR_EXACT_GAV_ATOMIC_SIMULATION",\n    }\n    out.write_text(json.dumps(payload,indent=2,sort_keys=True),encoding="utf-8")\n    print("[REPORT] "+str(out),flush=True)\n    print("[MONEY] %s"%("PROFITABLE_ATOMIC_SIMULATION" if good else "NO_PROFITABLE_ATOMIC_SIMULATION"),flush=True)\n    print("[MODE] execution_authority=FALSE real_money_moved=FALSE",flush=True)\n    return payload\n\nif __name__=="__main__":\n    run()\n',encoding="utf-8")
py_compile.compile(str(MOD),doraise=True)

TEST=ROOT/"test_qsb_059b_gav_reverse_atomic_composer.py"
TEST.write_text('import base64,unittest\nfrom qseries_v2.oracle_strategy_intelligence.solana_money import qsb059_gav_reverse_atomic as q\n\nclass T(unittest.TestCase):\n    def test_reverse_ix_direction_token_x_is_wsol(self):\n        c=q.c\n        old={k:getattr(c,k) for k in ("account","ata","pda","dlmm_arrays")}\n        c.account=lambda a:(b"x","TP")\n        c.ata=lambda owner,mint,tp:"ATA_"+mint\n        c.pda=lambda seeds,program:"PDA"\n        c.dlmm_arrays=lambda pool:[(1,"BIN1",b"x"),(2,"BIN2",b"x"),(3,"BIN3",b"x")]\n        try:\n            meta={"address":"11111111111111111111111111111111","token_x":c.WSOL,"token_y":c.DLMM}\n            ix=q.dlmm_reverse_ix("USER",meta,123,{"raw_out":456,"swap_for_y":False,"bins_crossed":1})\n            ac=[x["pubkey"] for x in ix["accounts"]]\n            self.assertEqual(ac[4],"ATA_"+c.DLMM)\n            self.assertEqual(ac[5],"ATA_"+c.WSOL)\n        finally:\n            for k,v in old.items():setattr(c,k,v)\n        print("[PASS] reverse DLMM instruction sources TOKEN and receives WSOL")\n\n    def test_atomic_order_pump_then_meteora(self):\n        c=q.c\n        old={k:getattr(c,k) for k in ("discover_dlmm","pump_tx","dlmm_quote","resolve_pump_instructions")}\n        old_ix=q.dlmm_reverse_ix\n        c.discover_dlmm=lambda token:{"address":"M","token_x":c.WSOL,"token_y":token}\n        c.pump_tx=lambda user,i,o,a:("TX",1000)\n        c.dlmm_quote=lambda meta,a,m:{"raw_out":1100,"swap_for_y":False,"bins_crossed":1}\n        c.resolve_pump_instructions=lambda tx:([\n          {"programId":"PRE","accounts":[],"data":""},\n          {"programId":c.PUMP,"accounts":[],"data":""},\n          {"programId":"POST","accounts":[],"data":""},\n        ],[])\n        q.dlmm_reverse_ix=lambda *a,**k:{"programId":c.DLMM,"accounts":[],"data":""}\n        try:\n            x=q.compose_reverse_atomic("U","T","P","M",0.000001)\n            programs=[i["programId"] for i in x["instructions"]]\n            self.assertEqual(programs,["PRE",c.PUMP,c.DLMM,"POST"])\n            self.assertGreater(x["pre_sim_net_lamports"],0)\n        finally:\n            for k,v in old.items():setattr(c,k,v)\n            q.dlmm_reverse_ix=old_ix\n        print("[PASS] atomic route order is PumpSwap BUY then Meteora SELL")\n\n    def test_no_broadcast(self):\n        src=open(q.__file__,encoding="utf-8").read()\n        self.assertNotIn("send(raw)",src)\n        self.assertNotIn("LIVE_BUY_SELL",src)\n        print("[PASS] QSB-059 cannot broadcast; exact simulation only")\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n',encoding="utf-8")
py_compile.compile(str(TEST),doraise=True)

